<script>
let purchaseItemIndex=0;
function openPurchasingModal(id){const element=document.getElementById(id);if(!element)return;element.classList.remove('hidden');element.classList.add('flex');document.body.style.overflow='hidden'}
function closePurchasingModal(id){const element=document.getElementById(id);if(!element)return;element.classList.add('hidden');element.classList.remove('flex');document.body.style.overflow=''}
function openOrderModal(){openPurchasingModal('orderModal');if(!document.querySelector('[data-purchase-item]'))addPurchaseItem();filterPurchaseSuppliers()}
function filterPurchaseSuppliers(){const branch=document.getElementById('purchaseBranch')?.value;const select=document.getElementById('purchaseSupplier');if(!select)return;select.querySelectorAll('option[data-branch]').forEach(option=>option.hidden=!branch||option.dataset.branch!==branch);if(select.selectedOptions[0]?.hidden)select.value=''}
function addPurchaseItem(){const template=document.getElementById('purchaseItemTemplate');const container=document.getElementById('purchaseItems');if(!template||!container)return;const wrapper=document.createElement('div');wrapper.innerHTML=template.innerHTML.replaceAll('__INDEX__',purchaseItemIndex++);container.appendChild(wrapper.firstElementChild);updatePurchaseTotal()}
function removePurchaseItem(button){button.closest('[data-purchase-item]')?.remove();if(!document.querySelector('[data-purchase-item]'))addPurchaseItem();updatePurchaseTotal()}
function updatePurchaseItem(select){const option=select.selectedOptions[0];const row=select.closest('[data-purchase-item]');const unit=option?.dataset.unit||'—';row.querySelector('[data-unit]').textContent=unit;row.querySelector('[data-stock-info]').textContent=option?.value?`Merkez stok: ${Number(option.dataset.stock||0).toLocaleString('tr-TR',{maximumFractionDigits:3})} ${unit}`:'Merkez stok: —'}
function updatePurchaseTotal(){const total=[...document.querySelectorAll('[data-purchase-item]')].reduce((sum,row)=>{const quantity=Number(row.querySelector('[data-quantity]')?.value||0);const price=Number(row.querySelector('[data-price]')?.value||0);const tax=Number(row.querySelector('[data-tax]')?.value||0);return sum+quantity*price*(1+tax/100)},0);const output=document.getElementById('purchaseOrderTotal');if(output)output.textContent=total.toLocaleString('tr-TR',{style:'currency',currency:'TRY'})}
function validatePurchaseOrder(){const selects=[...document.querySelectorAll('.purchase-product')];const values=selects.map(select=>select.value).filter(Boolean);const warning=document.getElementById('purchaseOrderWarning');let message='';if(values.length!==new Set(values).size)message='Aynı hammadde siparişe birden fazla kez eklenemez.';warning.textContent=message;warning.classList.toggle('hidden',!message);return !message}
function filterOrders(){const query=(document.getElementById('orderSearch')?.value||'').toLocaleLowerCase('tr-TR').trim();const status=document.getElementById('orderStatusFilter')?.value||'';let visible=0;document.querySelectorAll('[data-order-row]').forEach(row=>{const show=(!query||row.dataset.search.toLocaleLowerCase('tr-TR').includes(query))&&(!status||row.dataset.status===status);row.classList.toggle('hidden',!show);if(show)visible++});document.getElementById('noFilteredOrders')?.classList.toggle('hidden',visible>0)}
document.getElementById('orderSearch')?.addEventListener('input',filterOrders);document.getElementById('orderStatusFilter')?.addEventListener('change',filterOrders);
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('[role="dialog"].flex').forEach(dialog=>closePurchasingModal(dialog.id))});
@if(old('form_context')==='purchase_order') document.addEventListener('DOMContentLoaded',openOrderModal); @endif
</script>
@endsection
